import { test, expect } from '@playwright/test';

test.describe('Motion Preference - Reduced Motion', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should respect prefers-reduced-motion setting and disable animations', async ({ page }) => {
    // Set reduced motion preference using page.evaluate
    await page.evaluate(() => {
      document.documentElement.style.transition = 'none';
      document.documentElement.style.animation = 'none';
    });

    // Verify reduced motion class is applied
    const body = page.locator('body');
    await expect(body).toHaveClass(/reduced-motion/);

    // Click a button that normally triggers an animation
    const button = page.getByRole('button', { name: /animate/i });
    await button.click();

    // Verify animation class is not present
    const animationClass = page.locator('[class*="animate-fade"]');
    await expect(animationClass).not.toBeVisible();

    // Verify transition property is not set
    const transitionStyle = await page.evaluate(() => {
      return getComputedStyle(document.documentElement).transition;
    });
    expect(transitionStyle).toBe('none');

    // Verify content appears instantly without transition
    const content = page.locator('[data-testid="animated-content"]');
    await expect(content).toBeVisible();
  });

  test('should respect prefers-reduced-motion setting and disable animations when animation is disabled', async ({ page }) => {
    // Set reduced motion preference using page.evaluate
    await page.evaluate(() => {
      document.documentElement.style.transition = 'none';
      document.documentElement.style.animation = 'none';
    });

    // Verify reduced motion class is applied
    const body = page.locator('body');
    await expect(body).toHaveClass(/reduced-motion/);

    // Click a button that normally triggers an animation
    const button = page.getByRole('button', { name: /animate/i });
    await button.click();

    // Verify animation class is not present
    const animationClass = page.locator('[class*="animate-fade"]');
    await expect(animationClass).not.toBeVisible();

    // Verify transition property is not set
    const transitionStyle = await page.evaluate(() => {
      return getComputedStyle(document.documentElement).transition;
    });
    expect(transitionStyle).toBe('none');

    // Verify content appears instantly without transition
    const content = page.locator('[data-testid="animated-content"]');
    await expect(content).toBeVisible();
  });
});
